// We use the Verus verification framework to write two small,
// fully-specified, side‐effect‐free functions that return
// 32‐bit floating‐point vectors of length exactly 2.

use verus::prelude::*;

verus! {
    // make_pair: given any two f32 values, return a Vec<f32> of length 2
    // with those values in order.
    #[verus_fn]
    fn make_pair(a: f32, b: f32) -> Vec<f32>
        // Specification (ensures‐clause):
        //   1) The resulting vector has length exactly 2.
        //   2) Its 0th element is a, and its 1st element is b.
        ensures |v: Vec<f32>| v.len() == 2
                          && v@[0] == a
                          && v@[1] == b
    {
        let mut v = Vec::new();
        v.push(a);
        v.push(b);
        v
    }

    // lagline: a thin wrapper around make_pair, just renaming the arguments.
    #[verus_fn]
    fn lagline(off: f32, scl: f32) -> Vec<f32>
        // Same specification style:
        ensures |v: Vec<f32>| v.len() == 2
                          && v@[0] == off
                          && v@[1] == scl
    {
        make_pair(off, scl)
    }
}